func _apply_clip() -> void:
	if _rig_anim == null:
		return
	_rig_anim.stop()
	var clip: String = POSE_CLIPS.get(state, "")
	if clip != "" and _rig_mount.visible:
		_rig_anim.play(clip)
		_rig_anim.advance(0.0) # MANUAL mode: apply the frame-0 pose now (CLAUDE.md "Headless facts")

	var k: float = _hop_t / _hop_dur
	position = _hop_from.lerp(_hop_to, k)
	_set_lift(HOP_HEIGHT * sin(PI * k))
if _hurt_left > 0.0:
	_hurt_left -= dt
	if _hurt_left <= 0.0 and state == "hurt":
		set_state("idle")
if _recover_left > 0.0:
	_recover_left -= dt
	if _recover_left <= 0.0 and state == "recover":
		set_state("idle")
if _rig_anim != null and _rig_anim.is_playing():
	_rig_anim.advance(dt) # game time: stops while paused, scales with time_scale

match anim.track_get_type(i):
	Animation.TYPE_VALUE, Animation.TYPE_BEZIER:
		if sub == "":
			out.append("track %d: no property in '%s'" % [i, path])
			continue
		var base: String = sub.get_slice(":", 0)
		var found: bool = false
		for p: Dictionary in node.get_property_list():
			if p["name"] == base:
				found = true
				break
		if not found:
			out.append("track %d: %s has no property '%s'" % [i, node.get_class(), base])
